const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',quote:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',stock:'<path d="m12 3 9 5-9 5-9-5 9-5zM3 8v9l9 5 9-5V8M12 13v9M7.5 5.5l9 5"/>',shop:'<path d="M3 3h2l3 12h11l2-8H6M9 20h.01M18 20h.01"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/>',docs:'<path d="M7 3h13v15M4 6h13v15H4zM8 11h5M8 15h5"/>',media:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="m3 16 5-5 6 6 3-3 4 4"/><circle cx="16" cy="10" r="1"/>',finance:'<path d="M4 20V10h4v10M10 20V4h4v16M16 20v-7h4v7M2 20h20"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="m9 5 7 7-7 7"/>',alert:'<path d="m12 3 10 18H2zM12 9v4M12 17h.01"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.quote}</svg>`;
const routes=[['inicio','Visão geral','home'],['orcamentos','Propostas comerciais','quote'],['estoque','Estoque','stock'],['compras','Compras','shop'],['documentos','Documentos','docs'],['registros','Registros','media'],['financeiro','Financeiro','finance']];
const $=s=>document.querySelector(s);const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const num=n=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:2});const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const today=()=>new Date().toISOString().slice(0,10);const date=s=>{const d=new Date(s+'T12:00:00');return Number.isNaN(d.valueOf())?'':d.toLocaleDateString('pt-BR')};
const catalog=[{id:'tubo',name:'Tubo inox 1½ polegada',unit:'barra de 6 m',price:280,initial:8,min:3},{id:'montante',name:'Montante inox',unit:'un.',price:115,initial:12,min:4},{id:'suporte',name:'Suporte de parede',unit:'un.',price:38,initial:22,min:6},{id:'fixacao',name:'Kit de fixação',unit:'kit',price:18,initial:4,min:6},{id:'vidro',name:'Vidro para guarda-corpo',unit:'m²',price:320,initial:5,min:2},{id:'perfil',name:'Perfil para cobertura',unit:'barra de 6 m',price:210,initial:7,min:2},{id:'cobertura',name:'Vidro para cobertura',unit:'m²',price:290,initial:3,min:2}];
const services={guarda:'Guarda-corpo de inox',corrimao:'Corrimão de parede',vidro:'Guarda-corpo com vidro',cobertura:'Cobertura de vidro'};
function seed(){return {stock:Object.fromEntries(catalog.map(m=>[m.id,m.initial])),quotes:[{id:'DJP-001',client:'Ana Silva',phone:'',address:'Uberaba, Curitiba',service:'guarda',length:6,height:1.1,finish:'Polido',labor:1200,markup:25,payment:'50% de entrada e 50% na entrega',notes:'',total:3897.5,status:'Aprovado',created:today()},{id:'DJP-002',client:'Carlos Oliveira',phone:'',address:'Água Verde, Curitiba',service:'corrimao',length:4,height:1,finish:'Escovado',labor:550,markup:25,payment:'50% de entrada e 50% na entrega',notes:'',total:1317.5,status:'Enviado',created:today()},{id:'DJP-003',client:'Condomínio Exemplo',phone:'',address:'Centro, Curitiba',service:'vidro',length:8,height:1.1,finish:'Polido',labor:1600,markup:25,payment:'A combinar',notes:'',total:7550,status:'Rascunho',created:today()}],payments:[{id:'REC-001',quote:'DJP-001',description:'Entrada do guarda-corpo',amount:2410,date:today(),type:'entrada'}],expenses:[{id:'DES-001',description:'Materiais do guarda-corpo',amount:1450,date:today(),type:'saida'}]};}
let state;try{state=JSON.parse(localStorage.getItem('djp-demo-v1'))||seed();}catch{state=seed();}let draft=null,currentDoc=null,media=[],storageWarning=false;
function save(){try{localStorage.setItem('djp-demo-v1',JSON.stringify(state));}catch{if(!storageWarning){toast('Este navegador não permitiu salvar. As alterações ficam nesta sessão.');storageWarning=true;}}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const badge=s=>`<span class="badge ${s==='Aprovado'||s==='Recebido'?'green':s==='Enviado'?'gold':'gray'}">${esc(s)}</span>`;
function header(title,description,action=''){return `<div class="page-header"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function stats(items){return `<div class="summary-grid">${items.map(i=>`<div class="stat"><div class="stat-top">${i[0]}<span class="stat-icon">${icon(i[3])}</span></div><div class="stat-value">${i[1]}</div><div class="stat-note">${i[2]}</div></div>`).join('')}</div>`;}
function quoteRows(){return state.quotes.map(q=>`<tr><td><div class="table-main">${esc(q.client)}</div><div class="table-sub">${q.id}</div></td><td><div>${services[q.service]}</div><div class="table-sub">${num(q.length)} m</div></td><td>${money(q.total)}</td><td>${badge(q.status)}</td><td><button class="text-button" data-open-quote="${q.id}">Abrir</button></td></tr>`).join('');}
function quoteTable(){return `<div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>SERVIÇO</th><th>VALOR</th><th>STATUS</th><th></th></tr></thead><tbody>${quoteRows()}</tbody></table></div>`;}
function overview(){const approved=state.quotes.filter(q=>q.status==='Aprovado');const received=state.payments.reduce((s,p)=>s+p.amount,0);const due=Math.max(0,approved.reduce((s,q)=>s+q.total,0)-received);return header('Visão geral','Seu trabalho, da proposta comercial à entrega.',`<a class="button" href="#novo">${icon('plus')} Nova proposta comercial</a>`)+stats([['Propostas comerciais',state.quotes.length,'Neste demonstrativo','quote'],['A receber',money(due),'Serviços aprovados','finance'],['Em execução',approved.length,'Propostas comerciais aprovadas','stock'],['Estoque em atenção',catalog.filter(m=>state.stock[m.id]<m.min).length,'Materiais abaixo do mínimo','alert']])+`<div class="welcome-strip"><div><h2>Experimente sua próxima proposta comercial</h2><p>Escolha o serviço, informe as medidas e veja uma estimativa de materiais e valores.</p></div><a class="button" href="#novo">Criar proposta comercial</a></div><div class="two-columns"><section class="panel"><div class="panel-title"><h2>Propostas comerciais recentes</h2><a href="#orcamentos" class="text-button">Ver todos</a></div>${quoteTable()}</section><section class="panel"><div class="panel-title"><h2>Acompanhar o trabalho</h2></div><div class="work-item"><span class="work-symbol">${icon('stock')}</span><div><h3>Guarda-corpo de Ana Silva</h3><p>Exemplo de serviço em produção</p>${badge('Aprovado')}</div></div><div class="work-item"><span class="work-symbol">${icon('alert')}</span><div><h3>Conferir kits de fixação</h3><p>Saldo atual: ${num(state.stock.fixacao)} kits. Mínimo sugerido: 6.</p><a class="text-button" href="#estoque">Consultar estoque</a></div></div><div class="work-item"><span class="work-symbol">${icon('media')}</span><div><h3>Registros da visita</h3><p>Teste o envio de fotos e vídeos de uma obra.</p><a class="text-button" href="#registros">Adicionar registro</a></div></div></section></div>`;}
function budgets(){return header('Propostas comerciais','Propostas e dados de cada serviço.',`<a class="button" href="#novo">${icon('plus')} Nova proposta comercial</a>`)+`<section class="panel"><div class="panel-title"><h2>Propostas da DJP</h2><span class="muted" style="font-size:12px">${state.quotes.length} propostas</span></div>${quoteTable()}</section><p class="notice" style="margin-top:18px">Os clientes e valores iniciais são exemplos fictícios.</p>`;}
function newDraft(){return {id:null,client:'',phone:'',address:'',service:'guarda',length:6,height:1.1,finish:'Polido',labor:1200,markup:25,payment:'50% de entrada e 50% na entrega',commercialQty:1,commercialUnit:'serviço',warranty:'',notes:'',status:'Rascunho'};}
function field(label,name,value,type='text',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function quoteForm(){if(!draft)draft=newDraft();return header(draft.id?'Editar proposta comercial':'Nova proposta comercial','Informe os dados e experimente o cálculo de materiais.',`<a href="#orcamentos" class="button secondary">Voltar</a>`)+`<div class="quote-layout"><form id="quote-form" class="panel"><section class="form-section"><h3>01. Cliente e obra</h3><div class="fields">${field('Nome do cliente *','client',draft.client,'text','required maxlength="100" placeholder="Ex.: Maria Souza"')}${field('Telefone','phone',draft.phone,'tel','maxlength="30" placeholder="(41) 99999-9999"')}<div class="field full"><label for="address">Endereço da obra</label><input id="address" name="address" value="${esc(draft.address)}" maxlength="200" placeholder="Bairro, cidade ou endereço"></div></div></section><section class="form-section"><h3>02. Serviço e medidas</h3><div class="fields"><div class="field full"><label for="service">Tipo de serviço</label><select id="service" name="service">${Object.entries(services).map(([k,v])=>`<option value="${k}" ${k===draft.service?'selected':''}>${v}</option>`).join('')}</select></div>${field('Comprimento (m)','length',draft.length,'number','required min="0.1" max="100" step="0.1"')}${field(draft.service==='cobertura'?'Profundidade (m)':'Altura (m)','height',draft.height,'number','required min="0.1" max="20" step="0.1"')}<div class="field full"><label for="finish">Acabamento</label><select id="finish" name="finish"><option ${draft.finish==='Polido'?'selected':''}>Polido</option><option ${draft.finish==='Escovado'?'selected':''}>Escovado</option></select></div></div></section><section class="form-section"><h3>03. Valores e condições</h3><div class="fields">${field('Mão de obra e instalação (R$)','labor',draft.labor,'number','required min="0" max="1000000" step="0.01"')}${field('Acréscimo sobre o custo (%)','markup',draft.markup,'number','required min="0" max="300" step="1"')}${field('Quantidade comercial','commercialQty',draft.commercialQty||1,'number','required min="0.01" max="100000" step="0.01"')}<div class="field"><label for="commercialUnit">Unidade comercial</label><select id="commercialUnit" name="commercialUnit">${['serviço','peça'].map(u=>`<option ${u===(draft.commercialUnit||'serviço')?'selected':''}>${u}</option>`).join('')}</select></div><div class="field full"><label for="payment">Condições de pagamento</label><input id="payment" name="payment" value="${esc(draft.payment)}" maxlength="200"></div><div class="field full"><label for="warranty">Garantia</label><textarea id="warranty" name="warranty" maxlength="1000" placeholder="Informe o prazo, a cobertura e as condições de garantia">${esc(draft.warranty||'')}</textarea></div><div class="field full"><label for="notes">Observações</label><textarea id="notes" name="notes" maxlength="1000" placeholder="O que este serviço inclui?">${esc(draft.notes)}</textarea></div></div></section><div class="actions"><button class="button" type="submit">${icon('check')} Salvar proposta comercial</button><button class="button secondary" type="button" id="preview-quote">Visualizar documento</button></div></form><aside class="quote-side"><section class="panel"><div class="panel-title"><div><h2>Estimativa de materiais</h2><p id="service-summary"></p></div>${icon('stock')}</div><div class="panel-body"><ul class="material-list" id="materials"></ul></div><div class="totals" id="quote-totals"></div></section><div class="help"><strong>Cálculo ilustrativo.</strong> Este exemplo usa regras simplificadas e 10% de perda nas barras. Medidas, resistência, fixações e aproveitamento precisam de conferência da DJP antes de uma obra real. O acabamento ainda não altera os preços neste demonstrativo.</div></aside></div>`;}
function calc(q){const l=Number(q.length)||0,h=Number(q.height)||0;let amounts;if(q.service==='corrimao'){const supports=Math.ceil(l/1.5)+1;amounts={tubo:Math.ceil(l*1.1/6),suporte:supports,fixacao:supports};}else if(q.service==='cobertura'){amounts={perfil:Math.ceil((l+h)*2*1.1/6),cobertura:Number((l*h).toFixed(2)),fixacao:Math.ceil(l/1.5)+1};}else{const uprights=Math.ceil(l/1.2)+1;amounts={tubo:Math.ceil((q.service==='vidro'?l:l*3)*1.1/6),montante:uprights,fixacao:uprights};if(q.service==='vidro')amounts.vidro=Number((l*h).toFixed(2));}const rows=Object.entries(amounts).map(([id,qty])=>({...catalog.find(m=>m.id===id),qty}));const materials=rows.reduce((s,m)=>s+m.qty*m.price,0),labor=Number(q.labor)||0,cost=materials+labor,markup=cost*(Number(q.markup)||0)/100;return {rows,materials,labor,cost,markup,total:cost+markup};}
function collectDraft(){if(!$('#quote-form'))return draft;const data=new FormData($('#quote-form'));for(const [key,value]of data.entries())draft[key]=['length','height','labor','markup','commercialQty'].includes(key)?Number(value):value;return draft;}
function updateQuote(){const q=collectDraft(),c=calc(q);$('#service-summary').textContent=`${services[q.service]} · ${num(q.length)} m`;const lab=$('label[for="height"]');lab.textContent=q.service==='cobertura'?'Profundidade (m)':'Altura (m)';$('#materials').innerHTML=c.rows.map(m=>`<li><span>${m.name}<small class="table-sub" style="display:block">${m.unit} · ${money(m.price)}</small></span><strong>${num(m.qty)} ${m.unit==='m²'?'m²':m.unit.startsWith('barra')?'barras':m.unit==='kit'?'kits':'un.'}</strong></li>`).join('');$('#quote-totals').innerHTML=`<div class="total-row"><span>Materiais</span><strong>${money(c.materials)}</strong></div><div class="total-row"><span>Mão de obra e instalação</span><strong>${money(c.labor)}</strong></div><div class="total-row"><span>Acréscimo (${num(q.markup)}%)</span><strong>${money(c.markup)}</strong></div><div class="total-row grand-total"><span>Total da proposta comercial</span><strong>${money(c.total)}</strong></div>`;}
function inventory(){const low=catalog.filter(m=>state.stock[m.id]<m.min);return header('Estoque','Disponibilidade dos materiais e entradas de compra.')+`<div class="inventory-note">${icon('alert')}<div><strong>${low.length?`${low.length} material(is) abaixo do mínimo`:'Estoque acima dos mínimos sugeridos'}</strong><p>Os limites e saldos são exemplos. As entradas abaixo atualizam este demonstrativo.</p></div></div><section class="panel"><div class="panel-title"><h2>Materiais cadastrados</h2></div><div class="table-wrap"><table><thead><tr><th>MATERIAL</th><th>UNIDADE</th><th>SALDO</th><th>MÍNIMO</th><th>SITUAÇÃO</th></tr></thead><tbody>${catalog.map(m=>`<tr><td class="table-main">${m.name}</td><td>${m.unit}</td><td>${num(state.stock[m.id])}</td><td>${m.min}</td><td><span class="badge ${state.stock[m.id]<m.min?'red':'green'}">${state.stock[m.id]<m.min?'Repor':'Disponível'}</span></td></tr>`).join('')}</tbody></table></div></section><section class="panel" style="margin-top:24px"><div class="panel-title"><h2>Registrar entrada</h2></div><form id="stock-entry" class="panel-body entry-form"><div class="field"><label for="stock-material">Material</label><select id="stock-material">${catalog.map(m=>`<option value="${m.id}">${m.name} (${m.unit})</option>`).join('')}</select></div>${field('Quantidade','stock-qty',1,'number','min="0.01" max="100000" step="0.01" required')}<button class="button" type="submit">Adicionar ao estoque</button></form></section>`;}
let selectedMaterial='tubo',purchaseQty=1;
const suppliers=[{name:'Fornecedor A',mult:1,freight:45,days:'2 dias úteis'},{name:'Fornecedor B',mult:.94,freight:70,days:'4 dias úteis'},{name:'Fornecedor C',mult:1.08,freight:0,days:'Retirada no dia'}];
function shops(){const m=catalog.find(m=>m.id===selectedMaterial);const vals=suppliers.map(s=>s.mult*m.price*purchaseQty+s.freight),best=Math.min(...vals);return header('Comparar preços','A mesma especificação, com frete e prazo de cada fornecedor.')+`<p class="notice">Cotações fictícias. Este demonstrativo não consulta lojas ou preços em tempo real.</p><div class="shop-selector"><select id="shop-material" aria-label="Material para comparar">${catalog.map(i=>`<option value="${i.id}" ${i.id===m.id?'selected':''}>${i.name} (${i.unit})</option>`).join('')}</select><div class="field"><label for="shop-qty">Quantidade</label><input id="shop-qty" type="number" min="0.01" max="10000" step="0.01" value="${purchaseQty}" style="max-width:150px"></div></div><div class="shop-grid">${suppliers.map((s,i)=>`<section class="panel price-card ${vals[i]===best?'best':''}"><div class="eyebrow">${vals[i]===best?'MENOR TOTAL':'COTAÇÃO DE EXEMPLO'}</div><h2 class="price-name">${s.name}</h2><p>${m.name}</p><div class="price-number">${money(m.price*s.mult)}<small> / ${m.unit}</small></div><div class="price-row"><span>Quantidade</span><strong>${num(purchaseQty)}</strong></div><div class="price-row"><span>Frete</span><strong>${money(s.freight)}</strong></div><div class="price-row"><span>Prazo</span><strong>${s.days}</strong></div><div class="price-total">Total <strong>${money(vals[i])}</strong></div><button class="button ${vals[i]===best?'':'secondary'}" data-buy="${i}">Simular compra</button></section>`).join('')}</div><div class="help" style="margin-top:24px">A simulação registra a entrada no estoque e o custo no financeiro. Em uma versão completa, a equipe poderá cadastrar fornecedores e suas cotações.</div>`;}
function printExamples(){return `<section class="print-examples"><div class="page-header"><div><h2>Como ficam impressos</h2><p>Modelos em A4 com dados fictícios. Abra o PDF para ver os detalhes ou imprimir.</p></div></div><div class="print-grid">${[['orcamento','Proposta comercial','Serviços, valores, pagamento, garantia e assinaturas.'],['contrato','Contrato','Cláusulas numeradas e espaços para assinatura.']].map(([id,title,description])=>`<article class="panel print-card"><a class="print-image" href="assets/documentos/${id}-exemplo.pdf" target="_blank" rel="noopener" aria-label="Abrir PDF de ${title.toLowerCase()}"><img src="assets/documentos/${id}-previa.png" alt="Prévia do ${title.toLowerCase()} impresso em uma página A4" loading="lazy" width="1191" height="1684"></a><div class="panel-body"><h3>${title}</h3><p>${description}</p><div class="actions"><a class="button" href="assets/documentos/${id}-exemplo.pdf" target="_blank" rel="noopener">Abrir PDF</a><a class="button secondary" href="assets/documentos/${id}-exemplo.pdf" download="DJP-${id}-demonstrativo.pdf">Baixar PDF</a></div></div></article>`).join('')}</div><p class="notice">Estes PDFs mostram o visual de impressão e não acompanham alterações feitas nos propostas. O contrato é um modelo demonstrativo.</p></section>`;}
function documents(){return header('Propostas comerciais, contratos e recibos','Documentos com a identidade da DJP.')+printExamples()+`<div class="panel" style="margin-bottom:24px"><div class="panel-body field"><label for="doc-quote">Selecione uma proposta comercial</label><select id="doc-quote">${state.quotes.map(q=>`<option value="${q.id}">${q.id} · ${esc(q.client)} · ${services[q.service]}</option>`).join('')}</select></div></div><div class="doc-grid"><section class="panel doc-preview"><span class="work-symbol">${icon('docs')}</span><div><h3>Contrato de serviço</h3><p>Cliente, descrição do serviço, medidas e condições comerciais a partir da proposta comercial.</p><button class="button" id="make-contract">Visualizar contrato</button></div></section><section class="panel doc-preview"><span class="work-symbol">${icon('finance')}</span><div><h3>Recibo de pagamento</h3><p>Comprovante dos valores que você registrou como recebidos no financeiro.</p><button class="button secondary" id="go-receipts">Consultar recebimentos</button></div></section></div><div class="help" style="margin-top:24px">O contrato aqui demonstra o preenchimento dos dados. A versão definitiva usará o modelo aprovado pela DJP. Documentos deste ambiente levam a identificação de demonstração.</div>`;}
function records(){return header('Fotos e vídeos','Registros associados à visita e à execução do serviço.')+`<section class="panel" style="margin-bottom:24px"><div class="panel-body field"><label for="media-quote">Proposta comercial / serviço</label><select id="media-quote">${state.quotes.map(q=>`<option value="${q.id}">${q.id} · ${esc(q.client)}</option>`).join('')}</select></div></section><label class="media-upload">${icon('upload')}<strong>Adicionar fotos ou vídeos</strong><p>Selecione arquivos do computador ou celular. Limite de 25 MB por arquivo.</p><input id="media-input" type="file" accept="image/*,video/*" multiple></label><p class="notice">Os arquivos ficam somente nesta sessão e não são enviados para a empresa.</p><div class="media-grid">${media.map((m,i)=>`<article class="media-card">${m.type.startsWith('video')?`<video src="${m.url}" controls playsinline></video>`:`<img src="${m.url}" alt="${esc(m.name)}">`}<div>${esc(m.name)}<small>${esc(m.quote)} · ${num(m.size/1024/1024)} MB</small><button class="text-button" data-remove-media="${i}">Remover registro</button></div></article>`).join('')}</div>${!media.length?`<div class="empty">As fotos e os vídeos adicionados aparecerão aqui.</div>`:''}`;}
function finance(){const received=state.payments.reduce((s,p)=>s+p.amount,0),costs=state.expenses.reduce((s,p)=>s+p.amount,0),sold=state.quotes.filter(q=>q.status==='Aprovado').reduce((s,q)=>s+q.total,0);return header('Financeiro','Recebimentos e despesas dos serviços.')+stats([['Recebido',money(received),'Entradas registradas','finance'],['A receber',money(Math.max(0,sold-received)),'Propostas comerciais aprovadas','quote'],['Despesas',money(costs),'Saídas registradas','shop'],['Saldo',money(received-costs),'Recebido menos despesas','finance']])+`<section class="panel"><div class="panel-title"><h2>Registrar pagamento</h2></div><form id="payment-form" class="panel-body finance-input"><div class="field"><label for="payment-quote">Proposta comercial</label><select id="payment-quote">${state.quotes.map(q=>`<option value="${q.id}">${q.id} · ${esc(q.client)}</option>`).join('')}</select></div>${field('Valor recebido (R$)','payment-amount','','number','required min="0.01" max="1000000" step="0.01" placeholder="0,00"')}${field('Data','payment-date',today(),'date','required')}<button class="button" type="submit">Registrar recebimento</button></form></section><section class="panel" style="margin-top:24px"><div class="panel-title"><h2>Movimentações</h2></div><div class="table-wrap"><table><thead><tr><th>DESCRIÇÃO</th><th>DATA</th><th>TIPO</th><th>VALOR</th><th></th></tr></thead><tbody>${[...state.payments,...state.expenses].slice().reverse().map(p=>`<tr><td><div class="table-main">${esc(p.description)}</div><div class="table-sub">${esc(p.quote||p.id)}</div></td><td>${date(p.date)}</td><td><span class="badge ${p.type==='entrada'?'green':'red'}">${p.type==='entrada'?'Recebimento':'Despesa'}</span></td><td>${money(p.amount)}</td><td>${p.type==='entrada'?`<button class="button secondary small receipt-button" data-receipt="${p.id}">${icon('docs')} Ver recibo</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;}
function render(){let route=location.hash.slice(1)||'inicio';if(!['novo',...routes.map(r=>r[0])].includes(route))route='inicio';$('#nav').innerHTML=routes.map(([id,name,ic])=>`<a class="nav-link ${route===id||(route==='novo'&&id==='orcamentos')?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}>${icon(ic)}<span>${name}</span></a>`).join('');$('#crumb').textContent=route==='novo'?'Nova proposta comercial':routes.find(r=>r[0]===route)[1];const pages={inicio:overview,orcamentos:budgets,novo:quoteForm,estoque:inventory,compras:shops,documentos:documents,registros:records,financeiro:finance};$('#main').innerHTML=pages[route]();if(route==='novo'){updateQuote();$('#quote-form').addEventListener('input',updateQuote);$('#quote-form').addEventListener('change',updateQuote);$('#quote-form').addEventListener('submit',saveQuote);$('#preview-quote').onclick=()=>{if(!$('#quote-form').reportValidity())return;collectDraft();showDoc('quote',{...draft,total:calc(draft).total,id:draft.id||'PRÉVIA'});};}bind(route);}
function saveQuote(e){e.preventDefault();const q=collectDraft(),calculated=calc(q);if(!q.client.trim()||!Number.isFinite(calculated.total)||q.length<=0||q.height<=0)return;const saved={...q,client:q.client.trim(),total:calculated.total,created:today()};if(q.id){const index=state.quotes.findIndex(x=>x.id===q.id);state.quotes[index]=saved;}else{saved.id=`DJP-${String(state.quotes.length+1).padStart(3,'0')}`;state.quotes.unshift(saved);}save();draft={...saved};showDoc('quote',saved);toast('Proposta comercial salvo neste navegador.');}
function bind(route){document.querySelectorAll('[data-open-quote]').forEach(b=>b.onclick=()=>{draft={...state.quotes.find(q=>q.id===b.dataset.openQuote)};location.hash='novo';});document.querySelectorAll('a[href="#novo"]').forEach(a=>a.onclick=()=>{draft=newDraft();});if(route==='estoque')$('#stock-entry').onsubmit=e=>{e.preventDefault();const id=$('#stock-material').value,qty=Number($('#stock-qty').value);if(!Number.isFinite(qty)||qty<=0)return;state.stock[id]=Number((state.stock[id]+qty).toFixed(2));save();render();toast('Entrada registrada no estoque.');};if(route==='compras'){const shopChange=()=>{const qty=Number($('#shop-qty').value);if(!Number.isFinite(qty)||qty<=0||qty>10000){toast('Informe uma quantidade maior que zero, até 10.000.');return;}selectedMaterial=$('#shop-material').value;purchaseQty=qty;render();};$('#shop-material').onchange=shopChange;$('#shop-qty').onchange=shopChange;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const m=catalog.find(m=>m.id===selectedMaterial),s=suppliers[Number(b.dataset.buy)];if(!confirm(`Simular compra de ${num(purchaseQty)} ${m.unit} de ${m.name} em ${s.name}? Esta ação altera apenas os dados de exemplo.`))return;state.stock[m.id]=Number((state.stock[m.id]+purchaseQty).toFixed(2));state.expenses.push({id:`DES-${Date.now()}`,description:`${m.name} · ${s.name}`,amount:Number((m.price*s.mult*purchaseQty+s.freight).toFixed(2)),date:today(),type:'saida'});save();toast('Compra simulada. Estoque e financeiro atualizados.');});}if(route==='documentos'){$('#make-contract').onclick=()=>showDoc('contract',state.quotes.find(q=>q.id===$('#doc-quote').value));$('#go-receipts').onclick=()=>{location.hash='financeiro';};}if(route==='registros'){$('#media-input').onchange=e=>{const quote=$('#media-quote').value;for(const f of e.target.files){if(!f.type.startsWith('image/')&&!f.type.startsWith('video/')){toast('Selecione uma imagem ou um vídeo.');continue;}if(f.size>25*1024*1024){toast('O arquivo ultrapassa o limite de 25 MB.');continue;}media.push({name:f.name,size:f.size,type:f.type,quote,url:URL.createObjectURL(f)});}render();};document.querySelectorAll('[data-remove-media]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.removeMedia);URL.revokeObjectURL(media[i].url);media.splice(i,1);render();});}if(route==='financeiro'){$('#payment-form').onsubmit=e=>{e.preventDefault();const id=$('#payment-quote').value,q=state.quotes.find(q=>q.id===id),amount=Number($('#payment-amount').value);if(!Number.isFinite(amount)||amount<=0)return;const paid=state.payments.filter(p=>p.quote===id).reduce((s,p)=>s+p.amount,0);if(paid+amount>q.total+.01){toast(`O saldo desta proposta comercial é ${money(Math.max(0,q.total-paid))}.`);return;}const p={id:`REC-${String(state.payments.length+1).padStart(3,'0')}`,quote:id,description:`Pagamento de ${q.client}`,amount,date:$('#payment-date').value,type:'entrada'};state.payments.push(p);save();render();showDoc('receipt',q,p);toast('Recebimento registrado.');};document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>{const payment=state.payments.find(p=>p.id===b.dataset.receipt);showDoc('receipt',state.quotes.find(q=>q.id===payment.quote),payment);});}}
function documentHTML(kind,q,p){
 const receipt=kind==='receipt',contract=kind==='contract';
 const title=receipt?'Recibo de pagamento':contract?'Contrato de serviço':'Proposta comercial';
 const code=receipt?p.id:q.id;const value=receipt?p.amount:q.total;
 const spec=services[q.service];const commercialQty=Number(q.commercialQty)>0?Number(q.commercialQty):1;const commercialUnit=q.commercialUnit==='peça'?'peça':'serviço';const dimension=q.service==='cobertura'?'Profundidade':'Altura';
 const client='<div class="doc-parties"><section><span class="doc-label">'+(contract?'CONTRATANTE':'PREPARADO PARA')+'</span><h3>'+esc(q.client)+'</h3><p>'+esc(q.address||'Endereço a confirmar')+(q.phone?'<br>'+esc(q.phone):'')+'</p></section><section><span class="doc-label">'+(contract?'PRESTADORA':'RESPONSÁVEL PELA PROPOSTA')+'</span><h3>DJP Artefatos de Inox</h3><p>Rua Tenente Coronel Benjamin Lage, 551, Lj 3<br>Uberaba, Curitiba · PR<br>(41) 99555-5536 · djpinox.com.br<br>CNPJ: a preencher pela empresa</p></section></div>';
 const specifications='<div class="doc-specs"><div><span>Comprimento</span><strong>'+num(q.length)+' m</strong></div><div><span>'+dimension+'</span><strong>'+num(q.height)+' m</strong></div><div><span>Acabamento</span><strong>'+esc(q.finish)+'</strong></div><div><span>Instalação</span><strong>Inclusa na proposta</strong></div></div>';
 const payment='<div class="doc-conditions"><div><span class="doc-label">PAGAMENTO</span><p>'+esc(q.payment||'A combinar')+'</p></div><div><span class="doc-label">'+(contract?'PRAZO DE EXECUÇÃO':'VALIDADE DA PROPOSTA')+'</span><p>'+(contract?'A definir após conferência da obra.':'15 dias a partir da emissão.')+'</p></div></div>';
 let body;
 if(receipt){body=client+'<div class="doc-receipt-value"><span class="doc-label">VALOR RECEBIDO</span><strong>'+money(value)+'</strong><p>Recebimento em '+date(p.date)+'</p></div><section class="doc-section"><h3>Referência do pagamento</h3><p>A DJP Artefatos de Inox registra o recebimento do valor acima de <strong>'+esc(q.client)+'</strong>, referente ao serviço de <strong>'+esc(spec.toLowerCase())+'</strong> da proposta comercial '+esc(q.id)+'.</p></section><div class="doc-signatures"><div><span>DJP Artefatos de Inox</span><small>Responsável pelo recebimento</small></div></div>';
 }else if(contract){body=client+'<section class="doc-section"><div class="doc-section-title"><span>01</span><h3>Objeto e especificações do serviço</h3></div><p>'+esc(spec)+', conforme proposta comercial '+esc(q.id)+'.</p>'+specifications+'</section><section class="doc-section"><div class="doc-section-title"><span>02</span><h3>Valor e condições de pagamento</h3></div><div class="doc-investment"><div><span class="doc-label">VALOR DO SERVIÇO</span><small>Conforme proposta comercial indicado</small></div><strong>'+money(value)+'</strong></div>'+payment+'</section><section class="doc-section"><div class="doc-section-title"><span>03</span><h3>Conferência e execução</h3></div><p>As medidas finais, o cronograma, os materiais e as condições de instalação precisam de confirmação pela DJP antes da execução.</p></section><section class="doc-section"><div class="doc-section-title"><span>04</span><h3>Condições específicas</h3></div><p>'+esc(q.notes||'Escopo definitivo, responsabilidades, garantias e demais condições devem constar no modelo aprovado pela empresa.')+'</p></section><div class="doc-signatures"><div><span>DJP Artefatos de Inox</span><small>Prestadora</small></div><div><span>'+esc(q.client)+'</span><small>Contratante</small></div></div>';
 }else{body=client+'<section class="doc-section"><div class="doc-section-title"><span>01</span><h3>Seu projeto</h3></div><h4>'+esc(spec)+'</h4><p>Fornecimento e instalação conforme as especificações desta proposta.</p>'+specifications+'</section><section class="doc-section"><div class="doc-section-title"><span>02</span><h3>Composição comercial</h3></div><table class="doc-commercial"><thead><tr><th>SERVIÇO</th><th>QTD.</th><th>UNIDADE</th><th>VLR. UNIT.</th><th>VALOR TOTAL</th></tr></thead><tbody><tr><td><strong>'+esc(spec)+'</strong><small>Fornecimento e instalação</small></td><td>'+num(commercialQty)+'</td><td>'+esc(commercialUnit)+'</td><td>'+money(value/commercialQty)+'</td><td>'+money(value)+'</td></tr></tbody></table><div class="doc-investment"><div><span class="doc-label">INVESTIMENTO TOTAL</span><small>Materiais e instalação inclusos</small></div><strong>'+money(value)+'</strong></div></section><section class="doc-section"><div class="doc-section-title"><span>03</span><h3>Condições da proposta</h3></div>'+payment+'<p class="doc-detail">Prazo de execução a combinar após a conferência do local e das medidas.</p>'+(q.notes?'<div class="doc-notes"><span class="doc-label">OBSERVAÇÕES</span><p>'+esc(q.notes)+'</p></div>':'')+'</section><section class="doc-section"><div class="doc-section-title"><span>04</span><h3>Garantia</h3></div><p>'+esc(q.warranty||'Prazo, cobertura e condições de garantia a preencher pela DJP antes da aprovação.')+'</p></section><div class="doc-signatures"><div><span>DJP Artefatos de Inox</span><small>Assinatura do responsável</small></div><div><span>'+esc(q.client)+'</span><small>Assinatura / aceite da proposta</small></div></div>';
 }
 return '<article class="djp-document"><header class="doc-masthead"><div class="doc-logo"><img src="assets/logo.png" alt="Logo DJP Artefatos de Inox"></div><div class="doc-heading"><span class="doc-kicker">DJP ARTEFATOS DE INOX</span><h2>'+title+'</h2><div class="doc-reference"><span>'+esc(code)+'</span><span>Emissão: '+date(today())+'</span></div></div></header><div class="doc-company-line"><span>Corrimãos e guarda-corpos · Inox e vidraçaria</span><span>Curitiba e região</span></div><div class="doc-inner">'+body+'<div class="doc-demo"><strong>DEMONSTRAÇÃO</strong><span>Documento ilustrativo, sem validade comercial. '+(contract?'Estrutura visual para validação. O contrato definitivo usará o modelo aprovado pela DJP.':'Preços, especificações e condições sujeitos à validação da DJP.')+'</span></div></div><footer class="doc-footer"><span>DJP Artefatos de Inox</span><span>Rua Tenente Coronel Benjamin Lage, 551, Lj 3 · Uberaba, Curitiba</span></footer></article>';
}
function showDoc(kind,q,p){currentDoc={kind,q,p};$('#doc-title').textContent=kind==='quote'?'Proposta comercial com a identidade da DJP':kind==='contract'?'Modelo de contrato':'Recibo de pagamento';$('#document').innerHTML=documentHTML(kind,q,p);if(kind==='quote'&&q.id!=='PRÉVIA'){const box=document.createElement('div');box.className='actions';box.innerHTML=`<label class="field" style="flex:1"><span style="font-size:12px">Status da proposta comercial</span><select id="quote-status">${['Rascunho','Enviado','Aprovado'].map(s=>`<option ${q.status===s?'selected':''}>${s}</option>`).join('')}</select></label>`;$('#document').appendChild(box);$('#quote-status').onchange=e=>{const quote=state.quotes.find(x=>x.id===q.id);if(quote){quote.status=e.target.value;currentDoc.q.status=quote.status;if(draft?.id===q.id)draft.status=quote.status;save();toast('Status da proposta comercial atualizado.');}};}$('#doc-dialog').showModal();}
async function docFile(){
 const [r,cssResponse]=await Promise.all([fetch('assets/logo.png'),fetch('documents.css')]);if(!r.ok||!cssResponse.ok)throw new Error('Documento indisponível');
 const blob=await r.blob();const logo=await new Promise(res=>{const reader=new FileReader();reader.onload=()=>res(reader.result);reader.readAsDataURL(blob)});
 const html=documentHTML(currentDoc.kind,currentDoc.q,currentDoc.p).replace('src="assets/logo.png"','src="'+logo+'"');const css=await cssResponse.text();
 const source='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DJP Inox — Documento demonstrativo</title><style>body{margin:0;padding:32px 16px;background:#e9e9e5;font-family:Arial,sans-serif}.djp-document{max-width:790px;margin:auto;background:#fff;box-shadow:0 5px 35px #0001}'+css+'</style></head><body>'+html+'</body></html>';
 return new File([source],'DJP-'+currentDoc.kind+'-'+(currentDoc.p?.id||currentDoc.q.id)+'.html',{type:'text/html'});
}
$('#close-dialog').onclick=()=>{$('#doc-dialog').close();render();};$('#doc-dialog').addEventListener('close',()=>render());$('#print-doc').onclick=()=>window.print();$('#download-doc').onclick=async()=>{try{const f=await docFile(),u=URL.createObjectURL(f),a=document.createElement('a');a.href=u;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);toast('Documento baixado. Para PDF, use imprimir / salvar PDF.');}catch{toast('Não foi possível baixar o documento. Tente imprimir / salvar PDF.');}};$('#share-doc').onclick=async()=>{try{const f=await docFile();if(navigator.canShare?.({files:[f]}))await navigator.share({files:[f],title:'DJP Inox — Documento demonstrativo'});else{$('#download-doc').click();toast('Documento baixado para compartilhar.');}}catch(e){if(e.name!=='AbortError')toast('Use baixar documento para compartilhar o arquivo.');}};
$('#reset').onclick=()=>{if(!confirm('Recomeçar a demonstração? Seus propostas e alterações neste navegador serão substituídos pelos exemplos iniciais.'))return;media.forEach(m=>URL.revokeObjectURL(m.url));media=[];state=seed();draft=null;save();location.hash='inicio';render();toast('Demonstração reiniciada.');};window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});let deferredInstall;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('#install').hidden=false;});$('#install').onclick=async()=>{if(deferredInstall){await deferredInstall.prompt();deferredInstall=null;$('#install').hidden=true;}};if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});render();


